def name_operands(region,address,operation):
 if region!='Station' or address not in FUNCTIONS:return operation
 for old,new in RENAMES.items():operation=operation.replace('@Station.'+old+'.','@Station.'+new+'.')
 for old,new in LABEL_RENAMES.items():operation=operation.replace('@Station.'+old,'@Station.'+new)
 operation=re.sub(r'#([0-9A-F]{4})',lambda m:'@'+TARGETS[int(m[1],16)] if int(m[1],16) in TARGETS else m[0],operation)
 return operation.replace('CP #80','CP @EquipmentListConst.EndQuantity').replace('LD A, #FB','LD A, @EquipmentListConst.ShipMismatch').replace('LD BC, #0004','LD BC, @EquipmentListConst.ShipSetSize').replace('LD BC, #1800','LD BC, @EquipmentListConst.FirstCursor').replace('LD A, #18','LD A, @EquipmentListConst.FirstRowY').replace('LD A, #2D','LD A, @SystemNameConst.Dash').replace('ADD A, #04','ADD A, @EquipmentListConst.ColumnInset').replace('ADD A, #08','ADD A, @ScreenConst.PixelsPerChar')
